import dspy
from pydantic import BaseModel
from dspy.utils.dummies import DummyLM


class CalendarEvent(BaseModel):
    name: str
    date: str
    participants: dict[str, str]


seen_types = []


def write_invitation_letter(participant_name: str, event_info: CalendarEvent):
    seen_types.append(type(event_info).__name__)
    if participant_name not in event_info.participants:
        return None
    return f"It's my honor to invite {participant_name} to event {event_info.name} on {event_info.date}"


class InvitationSignature(dspy.Signature):
    participant_name: str = dspy.InputField()
    event_info: CalendarEvent = dspy.InputField()
    invitation_letter: str = dspy.OutputField()


lm = DummyLM(
    [
        {
            "next_thought": "I need to write an invitation letter for Alice.",
            "next_tool_name": "write_invitation_letter",
            "next_tool_args": {
                "participant_name": "Alice",
                "event_info": {
                    "name": "Science Fair",
                    "date": "Friday",
                    "participants": {"Alice": "female", "Bob": "male"},
                },
            },
        },
        {
            "next_thought": "I have the letter, so I can finish.",
            "next_tool_name": "finish",
            "next_tool_args": {},
        },
        {
            "reasoning": "Tool call succeeded.",
            "invitation_letter": "It's my honor to invite Alice to the Science Fair event on Friday.",
        },
    ]
)
dspy.configure(lm=lm)
react = dspy.ReAct(InvitationSignature, tools=[write_invitation_letter])

result = react(
    participant_name="Alice",
    event_info=CalendarEvent(
        name="Science Fair",
        date="Friday",
        participants={"Alice": "female", "Bob": "male"},
    ),
)

assert seen_types == ["CalendarEvent"]
assert result.invitation_letter == "It's my honor to invite Alice to the Science Fair event on Friday."
assert result.trajectory["tool_args_0"] == {
    "participant_name": "Alice",
    "event_info": {
        "name": "Science Fair",
        "date": "Friday",
        "participants": {"Alice": "female", "Bob": "male"},
    },
}
print("tool_saw_type:", seen_types[0])
print("trajectory_tool_args:", result.trajectory["tool_args_0"])
